/** Compute Entrypoint Contract
  *
  * guarantee CASE_01_desired_status_qualification
  * @param api_current_temperature incoming data port
  * @param api_desired_settings incoming data port
  * @param api_interface_facts outgoing data port
  */
pub fn compute_spec_CASE_01_desired_status_qualification_guarantee(
  api_current_temperature: Isolette_Thermostat_Rust::CurrentTemperature,
  api_desired_settings: Isolette_Thermostat_Rust::DesiredTemperatureSettings,
  api_interface_facts: Isolette_Thermostat_Rust::RegulatorInterfaceFacts) -> bool
{
  (api_interface_facts.interface_failure == !(api_desired_settings.lower_valid) | !(api_desired_settings.upper_valid)) &
    (api_interface_facts.current_valid == api_current_temperature.temperature_valid)
}

/** Compute Entrypoint Contract
  *
  * guarantee CASE_02_desired_range_availability
  * @param api_desired_settings incoming data port
  * @param api_control_basis outgoing data port
  * @param api_interface_facts outgoing data port
  */
pub fn compute_spec_CASE_02_desired_range_availability_guarantee(
  api_desired_settings: Isolette_Thermostat_Rust::DesiredTemperatureSettings,
  api_control_basis: Isolette_Thermostat_Rust::RegulatorControlBasis,
  api_interface_facts: Isolette_Thermostat_Rust::RegulatorInterfaceFacts) -> bool
{
  (api_interface_facts.range_available == !(api_interface_facts.interface_failure)) &
    (api_control_basis.range_available == api_interface_facts.range_available) &
    (implies!(
      api_interface_facts.range_available,
      (api_interface_facts.lower_dF == regulator_to_tenths(api_desired_settings.lower)) &
        (api_interface_facts.upper_dF == regulator_to_tenths(api_desired_settings.upper)) &
        (api_control_basis.lower_dF == api_interface_facts.lower_dF) &
        (api_control_basis.upper_dF == api_interface_facts.upper_dF)))
}

/** Compute Entrypoint Contract
  *
  * guarantee CASE_03_regulator_feedback
  * @param api_regulator_mode incoming data port
  * @param api_control_basis outgoing data port
  * @param api_regulator_feedback outgoing data port
  */
pub fn compute_spec_CASE_03_regulator_feedback_guarantee(
  api_regulator_mode: Isolette_Thermostat_Rust::ThermostatMode,
  api_control_basis: Isolette_Thermostat_Rust::RegulatorControlBasis,
  api_regulator_feedback: Isolette_Thermostat_Rust::RegulatorFeedback) -> bool
{
  (implies!(
    (api_regulator_mode == Isolette_Thermostat_Rust::ThermostatMode::INIT),
    (api_regulator_feedback.regulator_status == Isolette_Thermostat_Rust::ThermostatStatusValue::Init))) &
    (implies!(
      (api_regulator_mode == Isolette_Thermostat_Rust::ThermostatMode::NORMAL),
      (api_regulator_feedback.regulator_status == Isolette_Thermostat_Rust::ThermostatStatusValue::On) &
        (api_regulator_feedback.display_temperature == rounded_display_temperature(api_control_basis.current_value_dF)))) &
    (implies!(
      (api_regulator_mode == Isolette_Thermostat_Rust::ThermostatMode::FAILED),
      (api_regulator_feedback.regulator_status == Isolette_Thermostat_Rust::ThermostatStatusValue::Failed)))
}

/** Compute Entrypoint Contract
  *
  * guarantee preserve_regulator_control_basis
  * @param api_current_temperature incoming data port
  * @param api_control_basis outgoing data port
  * @param api_interface_facts outgoing data port
  */
pub fn compute_spec_preserve_regulator_control_basis_guarantee(
  api_current_temperature: Isolette_Thermostat_Rust::CurrentTemperature,
  api_control_basis: Isolette_Thermostat_Rust::RegulatorControlBasis,
  api_interface_facts: Isolette_Thermostat_Rust::RegulatorInterfaceFacts) -> bool
{
  (api_control_basis.current_value_dF == api_current_temperature.value_dF) &
    (api_control_basis.current_valid == api_interface_facts.current_valid)
}

/** Compute Entrypoint Contract
  *
  * guarantee preserve_display_temperature_domain
  * @param api_regulator_feedback outgoing data port
  */
pub fn compute_spec_preserve_display_temperature_domain_guarantee(api_regulator_feedback: Isolette_Thermostat_Rust::RegulatorFeedback) -> bool
{
  (api_regulator_feedback.display_temperature >= nominal_display_temperature()) &
    (api_regulator_feedback.display_temperature <= maximum_display_temperature())
}

/** CEP-T-Guar: Top-level guarantee contracts for manage_regulator_interface's compute entrypoint
  *
  * @param api_current_temperature incoming data port
  * @param api_desired_settings incoming data port
  * @param api_regulator_mode incoming data port
  * @param api_control_basis outgoing data port
  * @param api_interface_facts outgoing data port
  * @param api_regulator_feedback outgoing data port
  */
pub fn compute_CEP_T_Guar(
  api_current_temperature: Isolette_Thermostat_Rust::CurrentTemperature,
  api_desired_settings: Isolette_Thermostat_Rust::DesiredTemperatureSettings,
  api_regulator_mode: Isolette_Thermostat_Rust::ThermostatMode,
  api_control_basis: Isolette_Thermostat_Rust::RegulatorControlBasis,
  api_interface_facts: Isolette_Thermostat_Rust::RegulatorInterfaceFacts,
  api_regulator_feedback: Isolette_Thermostat_Rust::RegulatorFeedback) -> bool
{
  let r0: bool = compute_spec_CASE_01_desired_status_qualification_guarantee(api_current_temperature, api_desired_settings, api_interface_facts);
  let r1: bool = compute_spec_CASE_02_desired_range_availability_guarantee(api_desired_settings, api_control_basis, api_interface_facts);
  let r2: bool = compute_spec_CASE_03_regulator_feedback_guarantee(api_regulator_mode, api_control_basis, api_regulator_feedback);
  let r3: bool = compute_spec_preserve_regulator_control_basis_guarantee(api_current_temperature, api_control_basis, api_interface_facts);
  let r4: bool = compute_spec_preserve_display_temperature_domain_guarantee(api_regulator_feedback);

  return r0 && r1 && r2 && r3 && r4;
}

